-- Field-level access (Phase 2 slice 2.0, ADR-0024 decisions 2 and 3): the definition qualifiers
-- and the field rules of custom roles. Generated by prisma migrate diff, then the hand-written
-- CHECKs, grants and row-level security at the end.
-- CreateTable
CREATE TABLE "identity"."role_definition_scope" (
    "tenant_id" VARCHAR(32) NOT NULL,
    "role_id" UUID NOT NULL,
    "permission_key" VARCHAR(128) NOT NULL,
    "all_definitions" BOOLEAN NOT NULL,
    "definition_ids" UUID[],

    CONSTRAINT "role_definition_scope_pkey" PRIMARY KEY ("tenant_id","role_id","permission_key")
);

-- CreateTable
CREATE TABLE "identity"."role_field_rule" (
    "tenant_id" VARCHAR(32) NOT NULL,
    "role_id" UUID NOT NULL,
    "definition_id" UUID NOT NULL,
    "field_id" UUID NOT NULL,
    "mode" VARCHAR(8) NOT NULL,

    CONSTRAINT "role_field_rule_pkey" PRIMARY KEY ("tenant_id","role_id","definition_id","field_id")
);

-- AddForeignKey
ALTER TABLE "identity"."role_definition_scope" ADD CONSTRAINT "role_definition_scope_role_fkey" FOREIGN KEY ("tenant_id", "role_id") REFERENCES "identity"."role"("tenant_id", "id") ON DELETE RESTRICT ON UPDATE RESTRICT;

-- AddForeignKey
ALTER TABLE "identity"."role_field_rule" ADD CONSTRAINT "role_field_rule_role_fkey" FOREIGN KEY ("tenant_id", "role_id") REFERENCES "identity"."role"("tenant_id", "id") ON DELETE RESTRICT ON UPDATE RESTRICT;

-- CHECKs (hand-written; Prisma cannot express them). The tenant and key patterns repeat
-- role_tenant_id_check and the permission key pattern of platform/authz.
ALTER TABLE "identity"."role_definition_scope"
  ADD CONSTRAINT "role_definition_scope_tenant_id_check" CHECK ("tenant_id" ~ '^[a-z][a-z0-9-]{1,31}$'),
  ADD CONSTRAINT "role_definition_scope_permission_key_check" CHECK ("permission_key" ~ '^[a-z][a-z0-9-]*(\.[a-z][a-z0-9-]*){2}$'),
  ADD CONSTRAINT "role_definition_scope_definition_ids_check" CHECK (
    "definition_ids" IS NOT NULL
    AND ("definition_ids" = '{}' OR array_ndims("definition_ids") = 1)
    AND array_position("definition_ids", NULL) IS NULL
    AND cardinality("definition_ids") <= 256
    AND ("all_definitions" = (cardinality("definition_ids") = 0))
  );

ALTER TABLE "identity"."role_field_rule"
  ADD CONSTRAINT "role_field_rule_tenant_id_check" CHECK ("tenant_id" ~ '^[a-z][a-z0-9-]{1,31}$'),
  ADD CONSTRAINT "role_field_rule_mode_check" CHECK ("mode" IN ('hidden', 'read', 'edit'));

-- Grants. Qualifiers and field rules are inserted and deleted, never updated.
GRANT SELECT, INSERT, DELETE ON TABLE "identity"."role_definition_scope" TO "phoenix_app";
GRANT SELECT, INSERT, DELETE ON TABLE "identity"."role_field_rule" TO "phoenix_app";

-- Row-level security, enabled and forced (ADR-0002, ADR-0003).
ALTER TABLE "identity"."role_definition_scope" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "identity"."role_definition_scope" FORCE ROW LEVEL SECURITY;
CREATE POLICY "role_definition_scope_tenant_isolation" ON "identity"."role_definition_scope"
  AS PERMISSIVE FOR ALL TO "phoenix_app"
  USING ("tenant_id" = "platform"."current_tenant_id"())
  WITH CHECK ("tenant_id" = "platform"."current_tenant_id"());

ALTER TABLE "identity"."role_field_rule" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "identity"."role_field_rule" FORCE ROW LEVEL SECURITY;
CREATE POLICY "role_field_rule_tenant_isolation" ON "identity"."role_field_rule"
  AS PERMISSIVE FOR ALL TO "phoenix_app"
  USING ("tenant_id" = "platform"."current_tenant_id"())
  WITH CHECK ("tenant_id" = "platform"."current_tenant_id"());
